using System.Runtime.InteropServices;

namespace Refrigerator;

public static class Brand
{
    private const string LogoBase64 = "";

    public static Image Image()
    {
        using var ms = new MemoryStream(Convert.FromBase64String(LogoBase64));
        using var img = System.Drawing.Image.FromStream(ms);
        return new Bitmap(img);
    }

    public static Icon Icon()
    {
        using var bmp = new Bitmap(Image(), new Size(64,64));
        var handle = bmp.GetHicon();
        try { return (Icon)System.Drawing.Icon.FromHandle(handle).Clone(); }
        finally { DestroyIcon(handle); }
    }

    [DllImport("user32.dll")]
    private static extern bool DestroyIcon(IntPtr hIcon);
}
